import { useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

type StatusId = 'active' | 'risk' | 'over' | 'paused';

type Project = {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: StatusId;
};

const STATUSES: ReadonlyArray<{ id: StatusId; label: string }> = [
  { id: 'active', label: 'В работе' },
  { id: 'risk', label: 'Риск' },
  { id: 'over', label: 'Перерасход' },
  { id: 'paused', label: 'На паузе' },
];

const PROJECTS: ReadonlyArray<Project> = [
  { id: 'p-01', name: 'Atlas Migration', used: 412, quota: 1000, status: 'active' },
  { id: 'p-02', name: 'Billing Revamp', used: 870, quota: 1000, status: 'risk' },
  { id: 'p-03', name: 'Cold Storage', used: 120, quota: 800, status: 'paused' },
  { id: 'p-04', name: 'Data Lakehouse', used: 1340, quota: 1200, status: 'over' },
  { id: 'p-05', name: 'Edge Cache', used: 300, quota: 600, status: 'active' },
  { id: 'p-06', name: 'Fraud Signals', used: 590, quota: 700, status: 'risk' },
  { id: 'p-07', name: 'Gateway v3', used: 210, quota: 900, status: 'active' },
  { id: 'p-08', name: 'Hydra Search', used: 980, quota: 950, status: 'over' },
  { id: 'p-09', name: 'Insights API', used: 45, quota: 500, status: 'paused' },
  { id: 'p-10', name: 'Jobs Runner', used: 640, quota: 1000, status: 'active' },
  { id: 'p-11', name: 'Keyring Rotation', used: 720, quota: 800, status: 'risk' },
  { id: 'p-12', name: 'Ledger Sync', used: 155, quota: 400, status: 'active' },
];

const PAGE_SIZE = 5;
const RADIUS = 18;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

function quotaTone(percent: number): string {
  if (percent >= 100) return 'var(--jx-danger)';
  if (percent >= 80) return 'var(--jx-warning)';
  return 'var(--jx-accent)';
}

export default function ProjectSpendPanel() {
  const [selected, setSelected] = useState<StatusId[]>(['active', 'risk', 'over']);
  const [page, setPage] = useState(0);

  const filtered = useMemo(
    () => (selected.length === 0 ? [] : PROJECTS.filter((p) => selected.includes(p.status))),
    [selected],
  );

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, totalPages - 1);
  const rows = filtered.slice(safePage * PAGE_SIZE, safePage * PAGE_SIZE + PAGE_SIZE);

  const toggleStatus = (id: StatusId) => {
    setSelected((prev) => (prev.includes(id) ? prev.filter((s) => s !== id) : [...prev, id]));
    setPage(0);
  };

  const resetFilters = () => {
    setSelected(STATUSES.map((s) => s.id));
    setPage(0);
  };

  return (
    <section className="jx-panel jx-stack" aria-labelledby="spend-panel-title">
      <header className="jx-panel__header jx-stack">
        <h2 id="spend-panel-title" className="jx-title">
          Расход по проектам
        </h2>
        <div className="jx-cluster" role="group" aria-label="Фильтр по статусу">
          {STATUSES.map((status) => {
            const on = selected.includes(status.id);
            return (
              <button
                key={status.id}
                type="button"
                className="jx-chip"
                data-state={on ? 'on' : 'off'}
                aria-pressed={on}
                onClick={() => toggleStatus(status.id)}
              >
                <span className="jx-chip__label">{status.label}</span>
                {on ? (
                  <span className="jx-chip__dismiss" aria-hidden="true">
                    ×
                  </span>
                ) : null}
              </button>
            );
          })}
        </div>
      </header>

      {rows.length === 0 ? (
        <div className="jx-empty jx-stack" role="status">
          <p className="jx-empty__title">Нет проектов под выбранные фильтры</p>
          <p className="jx-empty__text" style={{ color: 'var(--jx-fg-muted)' }}>
            Снятые статусы скрывают все строки списка.
          </p>
          <Button type="button" onClick={resetFilters}>
            Сбросить фильтры
          </Button>
        </div>
      ) : (
        <ul className="jx-list" style={{ listStyle: 'none', margin: 0, padding: 0 }}>
          {rows.map((project) => {
            const percent = Math.round((project.used / project.quota) * 100);
            const tone = quotaTone(percent);
            const statusLabel =
              STATUSES.find((s) => s.id === project.status)?.label ?? project.status;
            return (
              <li key={project.id} className="jx-list__row jx-cluster">
                <span className="jx-list__title">{project.name}</span>
                <svg
                  className="jx-gauge"
                  width={48}
                  height={48}
                  viewBox="0 0 48 48"
                  role="img"
                  aria-label={`Квота ${project.name}: ${percent} процентов`}
                >
                  <circle
                    cx="24"
                    cy="24"
                    r={RADIUS}
                    fill="none"
                    stroke="var(--jx-border)"
                    strokeWidth="4"
                  />
                  <circle
                    cx="24"
                    cy="24"
                    r={RADIUS}
                    fill="none"
                    stroke={tone}
                    strokeWidth="4"
                    strokeLinecap="round"
                    strokeDasharray={CIRCUMFERENCE}
                    strokeDashoffset={CIRCUMFERENCE * (1 - Math.min(percent, 100) / 100)}
                    transform="rotate(-90 24 24)"
                  />
                  <text
                    x="24"
                    y="24"
                    textAnchor="middle"
                    dominantBaseline="central"
                    fill="var(--jx-fg)"
                    fontSize="10"
                  >
                    {percent}%
                  </text>
                </svg>
                <span className="jx-badge" data-status={project.status}>
                  {statusLabel}
                </span>
              </li>
            );
          })}
        </ul>
      )}

      {rows.length > 0 ? (
        <footer className="jx-cluster jx-panel__footer">
          <Button
            type="button"
            disabled={safePage === 0}
            onClick={() => setPage((p) => Math.max(0, p - 1))}
          >
            Назад
          </Button>
          <span aria-live="polite" style={{ color: 'var(--jx-fg-muted)' }}>
            Страница {safePage + 1} из {totalPages}
          </span>
          <Button
            type="button"
            disabled={safePage >= totalPages - 1}
            onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
          >
            Вперёд
          </Button>
        </footer>
      ) : null}
    </section>
  );
}

